--liquibase formatted sql
--changeset idea-support:create-idea-domain-v1
CREATE TABLE categories (id VARCHAR(36) PRIMARY KEY, name VARCHAR(50) NOT NULL, name_key VARCHAR(150) NOT NULL UNIQUE, kind VARCHAR(16) NOT NULL, created_by BIGINT NULL, use_count BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_category_user FOREIGN KEY (created_by) REFERENCES users(idx));
CREATE TABLE words (id VARCHAR(36) PRIMARY KEY, text VARCHAR(150) NOT NULL, text_key VARCHAR(150) NOT NULL UNIQUE, keywords TEXT NOT NULL);
CREATE TABLE category_words (id VARCHAR(36) PRIMARY KEY, category_id VARCHAR(36) NOT NULL, word_id VARCHAR(36) NOT NULL, score DOUBLE NOT NULL DEFAULT 1, CONSTRAINT uq_category_word UNIQUE(category_id,word_id), CONSTRAINT fk_cw_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_cw_word FOREIGN KEY(word_id) REFERENCES words(id));
CREATE TABLE ideas (id VARCHAR(36) PRIMARY KEY, category_id VARCHAR(36) NOT NULL, combo_key VARCHAR(128) NOT NULL UNIQUE, direction VARCHAR(200) NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, parent_idea_id VARCHAR(36) NULL, source VARCHAR(16) NOT NULL, hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_idea_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_idea_parent FOREIGN KEY(parent_idea_id) REFERENCES ideas(id));
CREATE TABLE idea_words (id VARCHAR(36) PRIMARY KEY, idea_id VARCHAR(36) NOT NULL, word_id VARCHAR(36) NOT NULL, position INT NOT NULL, CONSTRAINT uq_idea_position UNIQUE(idea_id,position), CONSTRAINT uq_idea_word UNIQUE(idea_id,word_id), CONSTRAINT fk_iw_idea FOREIGN KEY(idea_id) REFERENCES ideas(id), CONSTRAINT fk_iw_word FOREIGN KEY(word_id) REFERENCES words(id), CONSTRAINT ck_iw_position CHECK(position BETWEEN 0 AND 2));
CREATE TABLE recipes (idea_id VARCHAR(36) PRIMARY KEY, kind VARCHAR(16) NOT NULL, feasible BOOLEAN NOT NULL, summary TEXT NOT NULL, ingredients JSON NOT NULL, steps JSON NOT NULL, source VARCHAR(16) NOT NULL, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_recipe_idea FOREIGN KEY(idea_id) REFERENCES ideas(id));
CREATE TABLE posts (id VARCHAR(36) PRIMARY KEY, idea_id VARCHAR(36) NOT NULL, user_idx BIGINT NOT NULL, scope VARCHAR(16) NOT NULL, share_code VARCHAR(64) NOT NULL UNIQUE, hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT uq_post_owner_scope UNIQUE(idea_id,user_idx,scope), CONSTRAINT fk_post_idea FOREIGN KEY(idea_id) REFERENCES ideas(id), CONSTRAINT fk_post_user FOREIGN KEY(user_idx) REFERENCES users(idx), CONSTRAINT ck_post_scope CHECK(scope IN ('link','feed')));
CREATE TABLE reactions (id VARCHAR(36) PRIMARY KEY, post_id VARCHAR(36) NOT NULL, user_idx BIGINT NOT NULL, kind VARCHAR(16) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT uq_reaction_user UNIQUE(post_id,user_idx), CONSTRAINT fk_reaction_post FOREIGN KEY(post_id) REFERENCES posts(id), CONSTRAINT fk_reaction_user FOREIGN KEY(user_idx) REFERENCES users(idx), CONSTRAINT ck_reaction_kind CHECK(kind IN ('like','meh','dislike')));
CREATE TABLE match_cache (cache_key VARCHAR(64) PRIMARY KEY, input_text VARCHAR(200) NOT NULL, result JSON NOT NULL, expires_at TIMESTAMP(6) NOT NULL);
CREATE INDEX ix_category_order ON categories(kind,use_count,id);
CREATE INDEX ix_post_feed ON posts(scope,hidden,created_at,id);
CREATE INDEX ix_reaction_counts ON reactions(post_id,kind);
CREATE INDEX ix_match_expiry ON match_cache(expires_at);
